/** How many lines at the top of a file are searched for the notice that a tool wrote it. */
const HEADER_LINES = 12;

/**
 * The notices tools put at the top of what they write: `<auto-generated>` (C#), "Generated by the
 * protocol buffer compiler", `@generated`, "Code generated ... DO NOT EDIT", "automatically
 * generated". The notice must open a comment line (only comment marks and spaces before it), so a
 * comment or a string that merely talks about these notices, as this file does, is not one.
 */
const GENERATED_NOTICE =
  /^[\s/*#<!-]*(?:<auto-generated\b|@generated\b|generated by the protocol buffer compiler\b|code generated\b.*\bdo not edit\b|(?:this (?:file|code) (?:is|was) )?(?:automatically|auto)[- ]generated\b|this (?:file|code) was generated\b)/i;

/**
 * Whether the header of `source` says a tool generated the file. Nobody edits such a file by hand,
 * so a finding in it cannot be acted on: the fix belongs in the generator or its input.
 */
export function isGeneratedSource(source: string): boolean {
  return source.split('\n', HEADER_LINES).some((line) => GENERATED_NOTICE.test(line));
}

/** The note that tells the reader how many files were left out for this reason. */
export function describeGenerated(count: number): string {
  const one = count === 1;
  const files = one ? '1 generated file was' : `${count} generated files were`;
  const reason = one ? 'its header says it was generated' : 'their headers say they were generated';
  return `${files} not analyzed (${reason}).`;
}
